// Mesma lista de id_eap do fluxo 'EAP — tarefas' (levantada por SQL no
// Supabase, 2026-09-18). Manter as duas sincronizadas se um grupo novo
// aparecer.
const ID_EAP = [
  { id_eap: 51,  id_obra: 91,  nome_obra: 'Novo Nordisk - UB/SP' },
  { id_eap: 32,  id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 121, id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 66,  id_obra: 103, nome_obra: 'CNPEM - Auditório' },
  { id_eap: 73,  id_obra: 106, nome_obra: 'CNPEM - Faseado' },
  { id_eap: 86,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 87,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 88,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 89,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 90,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 94,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 110, id_obra: 108, nome_obra: 'Novo Nordisk - AP - Reforço' },
  { id_eap: 114, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 115, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 127, id_obra: 114, nome_obra: 'IPEN' },
];

// Janela de 2 dias (hoje + ontem), decisão explícita de 2026-09-18: só
// 'hoje' deixaria a execução horária sem recuperação se uma falhasse ou
// se o apontamento do dia entrasse com atraso na origem. Como o upsert é
// por (id, data_do_input), reprocessar o mesmo dia é idempotente.
const DIAS_JANELA = 2;
const datas = [];
for (let i = 0; i < DIAS_JANELA; i++) {
  const d = new Date();
  d.setDate(d.getDate() - i);
  datas.push(d.toISOString().slice(0, 10)); // YYYY-MM-DD
}

const combinacoes = [];
for (const g of ID_EAP) {
  for (const data of datas) combinacoes.push({ json: { ...g, data } });
}
return combinacoes;

// ATENÇÃO: o envelope deste endpoint ainda NÃO foi confirmado contra uma
// resposta real (o de /tarefas foi). O parse abaixo é tolerante: aceita
// {data:{...,<lista>}}, {data:[...]} ou [...] direto, e procura a
// primeira propriedade que seja array (avancos/apontamentos/tarefas/
// itens/registros). Se não achar, o erro traz o corpo cru pra ajustar
// sem adivinhação.
//
// Tipos seguem a tabela `Apontamentos` do Supabase (conferida por SQL):
// CUIDADO -- `qtd` e `avanco_atual` são TEXT aqui, ao contrário da tabela
// `EAP`, onde são double. `avanco_atual_p100`, `avanco_diario` e
// `meta_diaria` são double. `UUID` não é enviado: a coluna tem
// DEFAULT gen_random_uuid(), quem gera é o Postgres.

const ctx = $('Loop id_eap+data (1 por vez)').first().json;
const entrada = $input.first().json;

const bruto = typeof entrada === 'string' ? entrada
            : (typeof entrada.data === 'string' ? entrada.data
            : (typeof entrada.body === 'string' ? entrada.body : entrada));
let corpo;
try {
  corpo = typeof bruto === 'string' ? JSON.parse(bruto) : bruto;
} catch (e) {
  throw new Error(`id_eap ${ctx.id_eap} / ${ctx.data}: resposta nao e JSON. Corpo cru (1000 chars): ` + String(bruto).slice(0, 1000));
}

const raiz = (corpo && corpo.data !== undefined) ? corpo.data : corpo;
let itens = null;
let meta = {};
if (Array.isArray(raiz)) {
  itens = raiz;
} else if (raiz && typeof raiz === 'object') {
  meta = raiz;
  const chave = ['avancos', 'apontamentos', 'tarefas', 'itens', 'registros', 'data']
    .find(k => Array.isArray(raiz[k]));
  if (chave) itens = raiz[chave];
}
if (!Array.isArray(itens)) {
  throw new Error(`id_eap ${ctx.id_eap} / ${ctx.data}: nao achei a lista de avancos no envelope. Recebido: ` + JSON.stringify(corpo).slice(0, 800));
}

// Dia sem apontamento é estado válido (fim de semana, obra parada).
// IMPORTANTE: devolve 1 item com lista vazia em vez de `return []` --
// se este node não emitisse item nenhum, os nodes seguintes não rodariam
// e o loop nunca receberia o sinal de "próximo", travando a iteração dos
// grupos restantes. Com lista vazia, o POST no Supabase vira um array
// vazio (inócuo) e o MySQL recebe um SELECT no-op.
if (itens.length === 0) {
  return [{ json: { id_eap: ctx.id_eap, data: ctx.data, total: 0, linhas: [], sqlMySql: 'SELECT 1' } }];
}

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const txt = (v) => (v === null || v === undefined || v === '' ? null : String(v));

const linhas = itens.map(a => ({
  id: num(a.id),
  id_eap: num(a.id_eap) ?? ctx.id_eap,
  nome_eap: txt(a.nome_eap) ?? txt(meta.nome_eap),
  nome_obra: txt(a.nome_obra) ?? txt(meta.nome_obra) ?? ctx.nome_obra,
  data_do_input: txt(a.data_do_input) ?? ctx.data,
  edt: txt(a.edt),
  tarefa: txt(a.tarefa),
  qtd: txt(a.qtd),
  unidade: txt(a.unidade),
  avanco_atual: txt(a.avanco_atual),
  avanco_atual_p100: num(a.avanco_atual_p100),
  avanco_diario: num(a.avanco_diario),
  usuario_avanco_diario: txt(a.usuario_avanco_diario),
  meta_diaria: num(a.meta_diaria),
  status_qualidade: txt(a.status_qualidade),
}));

const invalidas = linhas.filter(l => l.id === null || !l.data_do_input).length;
if (invalidas) {
  throw new Error(`id_eap ${ctx.id_eap} / ${ctx.data}: ${invalidas} linha(s) sem id ou data_do_input -- sao a chave do upsert. 1o item recebido: ` + JSON.stringify(itens[0]).slice(0, 600));
}

const COLUNAS = Object.keys(linhas[0]);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));
const colsSql = COLUNAS.map(c => '`' + c + '`').join(',');
const tuplas = linhas.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const updSql = COLUNAS.filter(c => c !== 'id' && c !== 'data_do_input').map(c => '`' + c + '` = VALUES(`' + c + '`)').join(', ');
const sqlMySql = `INSERT INTO eap_apontamentos (${colsSql}) VALUES ${tuplas} ON DUPLICATE KEY UPDATE ${updSql}`;

return [{ json: { id_eap: ctx.id_eap, data: ctx.data, total: linhas.length, linhas, sqlMySql } }];
